class Reviewer322Memory extends MedicineProvisionalMemory {
 public array $qualifications=[],$appraisals=[];public bool $journalFault=false;
 public function qualificationLatest(int $user):?array {$rows=array_values(array_filter($this->qualifications,fn($r)=>(int)$r['user_id']===$user));return $rows?end($rows):null;}
 public function appendQualification(array $r):string {$id=(string)(count($this->qualifications)+1);$this->qualifications[$id]=['id'=>$id]+$r;if($this->journalFault){throw new PDOException('SYNTHETIC PRIVATE JOURNAL FAULT');}return $id;}
 public function appraisalLatest(string $id,int $revision):?array {$rows=array_values(array_filter($this->appraisals,fn($r)=>(string)$r['substance_id']===$id&&(int)$r['provisional_revision']===$revision));return $rows?end($rows):null;}
 public function appraisalReviewer(string $id):?int {$rows=array_values(array_filter($this->appraisals,fn($r)=>(string)$r['substance_id']===$id));return $rows?(int)end($rows)['reviewer_id']:null;}
 public function appendAppraisal(array $r):string {$id=(string)(count($this->appraisals)+1);$this->appraisals[$id]=['id'=>$id]+$r;return $id;}
 public function provisionalHistory(string $id):array {return array_values($this->provisionalRows[$id]??[]);}
 public function transaction(callable $a):mixed {$before=serialize([$this->qualifications,$this->appraisals]);try{return parent::transaction($a);}catch(Throwable $e){[$this->qualifications,$this->appraisals]=unserialize($before);throw $e;}}
}
